def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents a single quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # Check what follows the closing quote
            if i < len(line) and line[i] != ',':
                return None

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1

    return fields

